#!/bin/sh
# Regenerate docs/hackathon/history.md: the dated commit record behind the
# build log, from the local checkouts. Mechanical; do not edit the output.
set -e
cd "$(dirname "$0")/.."
OUT=docs/hackathon/history.md

repo() {
  name="$1"; dir="$2"; url="$3"
  if [ ! -d "$dir" ]; then
    echo "missing checkout $dir" >&2
    exit 1
  fi
  first=$(git -C "$dir" log --format='%h %ad' --date=format:'%Y-%m-%d' --reverse --since=2026-10-19T00:00:00 | head -1)
  latest=$(git -C "$dir" log --format='%h %ad' --date=format:'%Y-%m-%d' -1)
  window=$(git -C "$dir" rev-list --count --since=2026-10-19T00:00:00 HEAD)
  {
    echo "## $name"
    echo
    echo "Public: $url"
    echo
    echo "- First commit in the window: $first"
    echo "- Latest commit: $latest"
    echo "- Commits in the window (from 2026-10-19, Q-001): $window"
    echo
    echo '```'
    git -C "$dir" log --format='%h %ad %s' --date=format:'%Y-%m-%d' --reverse --since=2026-10-19T00:00:00
    echo '```'
    echo
  }
}

{
  echo "# Commit history behind the build log"
  echo
  echo "Generated by \`scripts/history.sh\` on $(date -u +%Y-%m-%dT%H:%M:%SZ) from the local checkouts; re-run it to refresh. The hackathon window counts work from 2026-10-19 (Q-001); this file lists that work only. ethereus-internal (fine-tune notes and rulings) is private and is not listed here; its cited hashes are in \`evidence.json\`."
  echo
  repo "ethereus — the computer in the weights" "$HOME/Dev/ethereus" "https://github.com/fraserbrownirl/ethereus"
  repo "ethereus-mac — the Mac runtime" "$HOME/Dev/ethereus-mac" "https://github.com/fraserbrownirl/ethereus-mac"
  repo "bursar-solana — the Solana prototype" "$HOME/Dev/bursar-solana" "https://github.com/fraserbrownirl/bursar-solana"
  repo "bursar-near — this repository" "$HOME/Dev/bursar-near" "https://github.com/fraserbrownirl/bursar-near"
} > "$OUT"
echo "history.md regenerated"
